import { test, expect } from '@playwright/test';

test('creates an order and verifies its server state', async ({ request }) => {
  const order = {
    advertiserId: 'adv-test',
    campaignId: 'cmp-test',
    lineItems: [{ sku: 'slot-1', quantity: 1 }]
  };

  const create = await request.post('/api/orders', {
