    headers: { Authorization: `Bearer ${process.env.API_TOKEN ?? ''}` }
  });
  expect(create.status()).toBe(201);
  const created = await create.json();
  expect(created).toEqual(expect.objectContaining({
    advertiserId: order.advertiserId,
    campaignId: order.campaignId
  }));
  expect(typeof created.id).toBe('string');

  const get = await request.get(`/api/orders/${created.id}`, {
    headers: { Authorization: `Bearer ${process.env.API_TOKEN ?? ''}` }
  });
  expect(get.ok()).toBeTruthy();
  expect(await get.json()).toEqual(expect.objectContaining({ id: created.id }));

  const remove = await request.delete(`/api/orders/${created.id}`, {
    headers: { Authorization: `Bearer ${process.env.API_TOKEN ?? ''}` }
  });
  expect([200, 202, 204]).toContain(remove.status());
});

