interface Order { id: string; status: 'CREATED' | 'APPROVED' | 'REJECTED' }

function isOrder(value: unknown): value is Order {
  if (typeof value !== 'object' || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return typeof candidate.id === 'string' &&
    (candidate.status === 'CREATED' || candidate.status === 'APPROVED' || candidate.status === 'REJECTED');
}

function parseOrder(value: unknown): Result<Order> {
  return isOrder(value) ? { ok: true, data: value } : { ok: false, error: 'Invalid order payload' };
}

