#!/usr/bin/env node
// Usage: kubectl get pods -A -o json | node nonready-pods.js
let input = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', chunk => { input += chunk; });
process.stdin.on('end', () => {
  const doc = JSON.parse(input);
  const pods = Array.isArray(doc.items) ? doc.items : [];
  for (const pod of pods) {
    const statuses = pod.status?.containerStatuses ?? [];
    const notReady = statuses.filter(status => status.ready !== true);
    if (notReady.length === 0 && statuses.length > 0) continue;
    const reasons = notReady.map(status => {
      const state = status.state ?? {};
      const detail = state.waiting ?? state.terminated ?? state.running ?? {};
      return `${status.name}: ${detail.reason ?? detail.message ?? 'not ready'}`;
    });
    const namespace = pod.metadata?.namespace ?? 'default';
    const name = pod.metadata?.name ?? '<unnamed>';
    console.log(`${namespace}/${name}\t${reasons.join('; ') || 'container status unavailable'}`);
  }
});
process.stdin.on('error', error => {
  console.error(error.message);
  process.exitCode = 1;
});

