import { test, expect } from '@playwright/test';

test('creates an order idempotently', async ({ request }) => {
  const key = `qa-${Date.now()}`;
  const body = { advertiserId: 'adv-1', lineItems: [{ campaignId: 'camp-1', quantity: 1 }] };
  const first = await request.post('/api/orders', {
    headers: { Authorization: `Bearer ${process.env.API_TOKEN ?? ''}`, 'Idempotency-Key': key },
    data: body
  });
  expect(first.status()).toBe(201);
  const firstJson = await first.json();
  expect(firstJson.id).toBeTruthy();

  const second = await request.post('/api/orders', {
    headers: { Authorization: `Bearer ${process.env.API_TOKEN ?? ''}`, 'Idempotency-Key': key },
    data: body
  });
  expect([200, 201]).toContain(second.status());
  const secondJson = await second.json();
  expect(secondJson.id).toBe(firstJson.id);
});

import java.util.*;

public class Duplicates {
    public static List<Integer> duplicates(int[] values) {
        if (values == null) return List.of();
        Set<Integer> seen = new HashSet<>();
        Set<Integer> reported = new LinkedHashSet<>();
        for (int value : values) {
            if (!seen.add(value)) reported.add(value);
        }
        return new ArrayList<>(reported);
    }

    public static void main(String[] args) {
        System.out.println(duplicates(new int[] {4, 2, 4, 3, 2, 2}));
    }
}

function duplicateValues(values) {
  const counts = new Map();
  for (const value of values) counts.set(value, (counts.get(value) ?? 0) + 1);

  const duplicates = [];
  const emitted = new Set();
  for (const value of values) {
    if (counts.get(value) > 1 && !emitted.has(value)) {
      duplicates.push(value);
      emitted.add(value);
    }
  }
  return duplicates;
}

