import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Optional;

public class FirstUniqueCharacter {
  public static Optional<Character> firstUnique(String input) {
    Map<Character, Integer> counts = new LinkedHashMap<>();
    for (char c : input.toCharArray()) counts.merge(c, 1, Integer::sum);
    for (char c : input.toCharArray()) {
      if (counts.get(c) == 1) return Optional.of(c);
    }
    return Optional.empty();
  }

  public static void main(String[] args) {
    System.out.println(firstUnique("swiss").orElseThrow());
  }
}
